package org.eclipse.rdf4j.sail.lmdb.benchmark;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.IOException;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.junit.jupiter.api.Test;

class OptionalFanoutBenchmarkTest {

	@Test
	void suppliedQueryHasExpectedProjectionAndOptionalShape() throws IOException {
		String query = OptionalFanoutBenchmark.loadQuery();
		Matcher variables = Pattern.compile("\\?(\\w+)").matcher(query);
		Set<String> names = new HashSet<>();
		while (variables.find()) {
			names.add(variables.group(1));
		}
		assertEquals(25, names.size());
		String projection = query.substring(query.indexOf("SELECT"), query.indexOf("WHERE"));
		Matcher projected = Pattern.compile("\\?(\\w+)").matcher(projection);
		int projectedCount = 0;
		while (projected.find()) {
			assertEquals(OptionalFanoutFixture.BINDINGS[projectedCount++], projected.group(1));
		}
		assertEquals(12, projectedCount);

		Matcher blocks = Pattern.compile("\\bOPTIONAL\\s*\\{|\\{|\\}").matcher(query);
		ArrayDeque<Boolean> optionalStack = new ArrayDeque<>();
		int optionalDepth = 0;
		int maxOptionalDepth = 0;
		int optionalCount = 0;
		while (blocks.find()) {
			String block = blocks.group();
			if (block.equals("}")) {
				if (optionalStack.pop()) {
					optionalDepth--;
				}
			} else {
				boolean optional = block.startsWith("OPTIONAL");
				optionalStack.push(optional);
				if (optional) {
					optionalCount++;
					maxOptionalDepth = Math.max(maxOptionalDepth, ++optionalDepth);
				}
			}
		}
		assertEquals(0, optionalStack.size());
		assertEquals(9, optionalCount);
		assertEquals(3, maxOptionalDepth);
	}

	@Test
	void smallFixturesConsumeEveryExpectedLexicalBinding() throws IOException {
		assertResult(1, 1, 83, 1_152, 2_793_119_168_170_060_480L);
		assertResult(2, 2, 94, 4_608, -3_970_798_365_781_632_704L);
		assertResult(1, 3, 89, 3_456, -7_845_893_282_001_393_600L);
	}

	@Test
	void defaultFixtureHasRequestedCardinalityAndStableDigest() throws IOException {
		OptionalFanoutBenchmark first = new OptionalFanoutBenchmark();
		OptionalFanoutBenchmark second = new OptionalFanoutBenchmark();
		try {
			first.setup();
			second.setup();
			assertEquals(3_278, first.dataset().statements());
			assertEquals(first.dataset().sha256(), second.dataset().sha256());
			assertEquals(1_152_000, OptionalFanoutFixture.expectedRows(100, 10));
		} finally {
			first.tearDown();
			second.tearDown();
		}
	}

	private static void assertResult(int measurements, int readings, long triples, long rows, long checksum)
			throws IOException {
		OptionalFanoutBenchmark benchmark = new OptionalFanoutBenchmark();
		benchmark.measurementCount = measurements;
		benchmark.readingsPerMeasurement = readings;
		try {
			benchmark.setup();
			assertEquals(triples, benchmark.dataset().statements());
			assertEquals(rows, OptionalFanoutFixture.expectedRows(measurements, readings));
			assertEquals(checksum, benchmark.runQuery());
		} finally {
			benchmark.tearDown();
		}
	}
}
